90	  final FileSystem _fileSystem;
91	  final ProcessManager _processManager;
92	  final FileSystemUtils _fileSystemUtils;
93	  final ProcessUtils _processUtils;
94	  final XcodeProjectInterpreter _xcodeProjectInterpreter;
95	  final Logger _logger;
96	  final Platform _platform;
97	
98	  Future<String> _versionText;
99	
100	  String get cocoaPodsMinimumVersion => '1.6.0';
101	  String get cocoaPodsRecommendedVersion => '1.9.0';
102	
103	  Future<bool> get isInstalled =>
104	    _processUtils.exitsHappy(<String>['which', 'pod']);
105	
106	  Future<String> get cocoaPodsVersionText {
107	    _versionText ??= _processUtils.run(
108	      <String>['pod', '--version'],
109	      environment: <String, String>{
110	        'LANG': 'en_US.UTF-8',
111	      },
112	    ).then<String>((RunResult result) {
113	      return result.exitCode == 0 ? result.stdout.trim() : null;
114	    }, onError: (dynamic _) => null);
115	    return _versionText;
116	  }
117	
118	  Future<CocoaPodsStatus> get evaluateCocoaPodsInstallation async {
119	    if (!(await isInstalled)) {
120	      return CocoaPodsStatus.notInstalled;
121	    }
122	    final String versionText = await cocoaPodsVersionText;
123	    if (versionText == null) {
124	      return CocoaPodsStatus.brokenInstall;
125	    }
126	    try {
127	      final Version installedVersion = Version.parse(versionText);
128	      if (installedVersion == null) {
129	        return CocoaPodsStatus.unknownVersion;
130	      }
131	      if (installedVersion < Version.parse(cocoaPodsMinimumVersion)) {
132	        return CocoaPodsStatus.belowMinimumVersion;
133	      }
134	      if (installedVersion < Version.parse(cocoaPodsRecommendedVersion)) {
135	        return CocoaPodsStatus.belowRecommendedVersion;
136	      }
137	      return CocoaPodsStatus.recommended;
138	    } on FormatException {
139	      return CocoaPodsStatus.notInstalled;
140	    }
141	  }
