152	  ///
153	  /// See https://github.com/CocoaPods/CocoaPods/blob/master/lib/cocoapods/config.rb#L138
154	  /// for details of this variable.
155	  Future<bool> get isCocoaPodsInitialized async {
156	    final Version installedVersion = Version.parse(await cocoaPodsVersionText);
157	    if (installedVersion != null && installedVersion >= Version.parse('1.8.0')) {
158	      return true;
159	    }
160	    final String cocoapodsReposDir = _platform.environment['CP_REPOS_DIR']
161	      ?? _fileSystem.path.join(_fileSystemUtils.homeDirPath, '.cocoapods', 'repos');
162	    return _fileSystem.isDirectory(_fileSystem.path.join(cocoapodsReposDir, 'master'));
163	  }
